class Countdown:
    def __init__(self, start):
        self.cur = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.cur <= 0:
            raise StopIteration
        v = self.cur
        self.cur -= 1
        return v

for n in Countdown(3):
    print(n)

