class CodeIter:
    def __init__(self, codes):
        self.codes = codes
        self.i = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.i == len(self.codes):
            raise StopIteration
        c = self.codes[self.i]
        self.i += 1
        if not c.isdigit():
            raise ValueError(c + " 는 숫자 코드가 아니에요")
        return int(c)

try:
